mapper.update:
UPDATE t_cluster_reclassification_run SET run_status='FINALIZING',
    lease_expires_at=DATE_ADD(NOW(3),INTERVAL 2 MINUTE),updated_at=NOW(3)
    WHERE id=#{id} AND run_status='RUNNING' AND lease_holder=#{holder}

UPDATE t_cluster_reclassification_run SET run_status='COMPLETED',lease_holder=NULL,
    lease_expires_at=NULL,completed_at=NOW(3),updated_at=NOW(3)
    WHERE id=#{id} AND run_status='FINALIZING' AND lease_holder=#{holder}

UPDATE t_cluster_reclassification_run SET run_status='FAILED',lease_holder=NULL,
    lease_expires_at=NULL,error_detail=#{detail},updated_at=NOW(3) WHERE id=#{id}
    AND (lease_holder=#{holder} OR lease_holder IS NULL)
